INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'future', 'n./adj.', '/ˈfjuːtʃə(r)/', '未来;将来;未来的', 'The future home will take care of nearly all the housework.', '未来的家几乎会包办所有家务。', 'Future Living', 1, 0, 'senior', 'wordlist', 'elective1', 'U4', 'the future home', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'security', 'n.', '/sɪˈkjʊərəti/', '安全;保护措施;安全工作', 'The home computer will oversee the security of the whole house.', '家用电脑会监管整座房子的安全。', 'Future Living', 2, 0, 'senior', 'wordlist', 'elective1', 'U4', 'home security', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'servant', 'n.', '/ˈsɜːvənt/', '仆人;佣人', 'This discreet electronic servant will control everything in the home.', '这位不张扬的电子仆人将掌控家中的一切。', 'Future Living', 3, 0, 'senior', 'wordlist', 'elective1', 'U4', 'an electronic servant', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'humidity', 'n.', '/hjuːˈmɪdəti/', '湿度;潮湿', 'The smart system can adjust the temperature and humidity automatically.', '智能系统能自动调节温度和湿度。', 'Future Living', 4, 0, 'senior', 'wordlist', 'elective1', 'U4', 'control the humidity', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'lighting', 'n.', '/ˈlaɪtɪŋ/', '照明;灯光;布光', 'You can change the lighting in any room with a single tap on your phone.', '你只需在手机上轻点一下就能改变任何房间的灯光。', 'Future Living', 5, 0, 'senior', 'wordlist', 'elective1', 'U4', 'soft lighting', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'gadget', 'n.', '/ˈɡædʒɪt/', '小器具;小装置', 'The home computer will manage all the household gadgets for you.', '这台家用电脑会替你管理所有家用小装置。', 'Future Living', 6, 0, 'senior', 'wordlist', 'elective1', 'U4', 'household gadgets', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'chore', 'n.', '/tʃɔː(r)/', '日常事务;例行家务', 'In the future home, robots will do most of the cleaning chores.', '在未来的家里,机器人会做大部分清洁家务。', 'Future Living', 7, 0, 'senior', 'wordlist', 'elective1', 'U4', 'cleaning chores', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'button', 'n.', '/ˈbʌtn/', '按钮;纽扣', 'Push a button and the walls will move backwards or forwards.', '按一下按钮,墙壁就会向后或向前移动。', 'Future Living', 8, 0, 'senior', 'wordlist', 'elective1', 'U4', 'push a button', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'forwards', 'adv.', '/ˈfɔːwədz/', '向前', 'At the touch of a button, the walls slide forwards to make the room smaller.', '轻触按钮,墙壁就向前滑动,把房间变小。', 'Future Living', 9, 0, 'senior', 'wordlist', 'elective1', 'U4', 'move forwards', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'integrated', 'adj.', '/ˈɪntɪɡreɪtɪd/', '综合的;各部分密切协调的;完整统一的', 'Simply place the clothes in the integrated laundry until they come out ready to wear.', '只需把衣服放进一体化洗衣装置,出来时就能直接穿了。', 'Future Living', 10, 0, 'senior', 'wordlist', 'elective1', 'U4', 'an integrated laundry', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fabric', 'n.', '/ˈfæbrɪk/', '织物;布料', 'The new easy-care fabric never needs ironing after washing.', '这种免熨烫的新布料洗后无需熨烫。', 'Future Living', 11, 0, 'senior', 'wordlist', 'elective1', 'U4', 'easy-care fabric', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'socket', 'n.', '/ˈsɒkɪt/', '(电源)插座', 'Each room will have a power wall instead of an electric socket.', '每个房间都会有一面电力墙,而不是电源插座。', 'Future Living', 12, 0, 'senior', 'wordlist', 'elective1', 'U4', 'an electric socket', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'attach', 'v.', '/əˈtætʃ/', '把……固定;把……附在(……上)', 'You will be able to attach any electrical appliance to the power wall.', '你可以把任何电器附在那面电力墙上。', 'Future Living', 13, 0, 'senior', 'wordlist', 'elective1', 'U4', 'attach to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'electrical', 'adj.', '/ɪˈlektrɪkl/', '电的;用电的;电动的', 'Almost every electrical appliance in the home can be controlled by your phone.', '家里几乎每件电器都能用手机控制。', 'Future Living', 14, 0, 'senior', 'wordlist', 'elective1', 'U4', 'electrical appliances', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'appliance', 'n.', '/əˈplaɪəns/', '(家用)电器;器具', 'A smart home connects every appliance into one network.', '智能家居把每件电器连成一个网络。', 'Future Living', 15, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a home appliance', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'old-fashioned', 'adj.', '/ˌəʊld ˈfæʃnd/', '陈旧的;过时的;不时髦的', 'Old-fashioned tools such as the duster will soon be gone.', '像抹布这样过时的工具很快就会消失。', 'Future Living', 16, 0, 'senior', 'wordlist', 'elective1', 'U4', 'old-fashioned tools', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'duster', 'n.', '/ˈdʌstə(r)/', '抹布;掸子', 'The good old duster will disappear once the air is filtered clean.', '一旦空气被过滤干净,那老式的抹布就会消失。', 'Future Living', 17, 0, 'senior', 'wordlist', 'elective1', 'U4', 'the good old duster', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'filter', 'v./n.', '/ˈfɪltə(r)/', '过滤;滤器', 'The system will filter the air and then scent it with your favourite perfume.', '系统会过滤空气,再给它加上你最喜欢的香味。', 'Future Living', 18, 0, 'senior', 'wordlist', 'elective1', 'U4', 'filter the air', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'scent', 'v./n.', '/sent/', '使具有香味;香味', 'After cleaning, the home will scent the air with a fresh smell.', '清洁之后,家里会给空气加上清新的香味。', 'Future Living', 19, 0, 'senior', 'wordlist', 'elective1', 'U4', 'scent the air', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'perfume', 'n.', '/ˈpɜːfjuːm/', '芳香;香味', 'Each room can be filled with your favourite perfume at any time.', '每个房间随时都能充满你最喜欢的香味。', 'Future Living', 20, 0, 'senior', 'wordlist', 'elective1', 'U4', 'your favourite perfume', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'entrance', 'n.', '/ˈentrəns/', '大门;入口;通道', 'The sitting-room door will be the entrance to a world full of adventures.', '客厅的门将成为通往一个充满冒险世界的入口。', 'Future Living', 21, 0, 'senior', 'wordlist', 'elective1', 'U4', 'the entrance to', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'adventure', 'n.', '/ədˈventʃə(r)/', '冒险;冒险经历;奇遇', 'Inside the future home you can enjoy endless adventures without leaving your seat.', '在未来的家里,你足不离座就能享受无尽的冒险。', 'Future Living', 22, 0, 'senior', 'wordlist', 'elective1', 'U4', 'endless adventures', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'simulator', 'n.', '/ˈsɪmjuleɪtə(r)/', '模拟装置;模拟器', 'When you get bored, a simulator can give you any experience from surfing to skiing.', '当你感到无聊时,模拟器能带给你从冲浪到滑雪的各种体验。', 'Future Living', 23, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a flight simulator', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'surfing', 'n.', '/ˈsɜːfɪŋ/', '冲浪运动', 'With the simulator, you can try surfing on a huge wave at home.', '借助模拟器,你能在家里体验在巨浪上冲浪。', 'Future Living', 24, 0, 'senior', 'wordlist', 'elective1', 'U4', 'go surfing', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'automatically', 'adv.', '/ˌɔːtəˈmætɪkli/', '自动地', 'At seven in the morning, my lights turn on automatically to wake me up.', '早上七点,我的灯会自动亮起把我叫醒。', 'Future Living', 25, 0, 'senior', 'wordlist', 'elective1', 'U4', 'turn on automatically', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'wardrobe', 'n.', '/ˈwɔːdrəʊb/', '衣柜;衣橱', 'Still sleepy, I find my uniform in the wardrobe and put it on.', '睡眼惺忪中,我从衣柜里找到校服穿上。', 'Future Living', 26, 0, 'senior', 'wordlist', 'elective1', 'U4', 'find clothes in the wardrobe', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'housekeeper', 'n.', '/ˈhaʊskiːpə(r)/', '管家;家务主管', 'Lina is my family''s housekeeper, and she has been with me all my life.', '莉娜是我家的管家,她陪伴了我一生。', 'Future Living', 27, 0, 'senior', 'wordlist', 'elective1', 'U4', 'the family housekeeper', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'nanny', 'n.', '/ˈnæni/', '保姆', 'When I was younger, the robot was my nanny and looked after me.', '我小时候,这个机器人是我的保姆,照顾着我。', 'Future Living', 28, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a reliable nanny', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'advertise', 'v.', '/ˈædvətaɪz/', '做广告;宣传', 'The robot was advertised as a reliable helper for busy families.', '这款机器人被宣传为忙碌家庭的可靠帮手。', 'Future Living', 29, 0, 'senior', 'wordlist', 'elective1', 'U4', 'advertise as', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'reliable', 'adj.', '/rɪˈlaɪəbl/', '可信赖的;可依靠的', 'A good home robot must be a reliable helper that never lets you down.', '一个好的家用机器人必须是从不让你失望的可靠帮手。', 'Future Living', 30, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a reliable helper', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'quantity', 'n.', '/ˈkwɒntəti/', '数量;数额', 'Each house receives food in a carefully controlled quantity, no more and no less.', '每户人家收到的食物数量都受到严格控制,不多也不少。', 'Future Living', 31, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a controlled quantity', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'overpopulation', 'n.', '/ˌəʊvəˌpɒpjuˈleɪʃn/', '人口过剩', 'The government says the planet can no longer deal with overpopulation.', '政府说地球再也无法应对人口过剩了。', 'Future Living', 32, 0, 'senior', 'wordlist', 'elective1', 'U4', 'the problem of overpopulation', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'error', 'n.', '/ˈerə(r)/', '错误;差错', 'Robots perform surgery with less room for error than humans.', '机器人做手术比人类出错的余地更小。', 'Future Living', 33, 0, 'senior', 'wordlist', 'elective1', 'U4', 'less room for error', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'interconnect', 'v.', '/ˌɪntəkəˈnekt/', '(使)相互联系;相互连接', 'From my window, all I can see are grey buildings and interconnecting tunnels.', '从窗口望出去,我只看到灰色的建筑和相互连接的隧道。', 'Future Living', 34, 0, 'senior', 'wordlist', 'elective1', 'U4', 'interconnecting tunnels', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'tunnel', 'n.', '/ˈtʌnl/', '地道;隧道', 'We have always walked through the tunnels to get to school.', '我们一直都是穿过隧道去上学的。', 'Future Living', 35, 0, 'senior', 'wordlist', 'elective1', 'U4', 'walk through the tunnel', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'skyscraper', 'n.', '/ˈskaɪskreɪpə(r)/', '摩天大楼', 'The city is full of grey skyscrapers that all look the same.', '这座城市满是看上去一模一样的灰色摩天大楼。', 'Future Living', 36, 0, 'senior', 'wordlist', 'elective1', 'U4', 'grey skyscrapers', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'identical', 'adj.', '/aɪˈdentɪkl/', '完全相同的;一模一样的', 'From far away, the buildings are all identical, like grey boxes.', '从远处看,这些建筑全都一模一样,像灰色的盒子。', 'Future Living', 37, 0, 'senior', 'wordlist', 'elective1', 'U4', 'identical buildings', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'spot', 'v.', '/spɒt/', '看见;注意到', 'I can just spot my school over to the right of the tower.', '我能勉强看见塔楼右边的学校。', 'Future Living', 38, 0, 'senior', 'wordlist', 'elective1', 'U4', 'spot my school', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'recycle', 'v.', '/ˌriːˈsaɪkl/', '回收利用;再利用', 'The children in the city have always breathed recycled air.', '城里的孩子一直呼吸着回收再利用的空气。', 'Future Living', 39, 0, 'senior', 'wordlist', 'elective1', 'U4', 'recycled air', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'advance', 'n./v.', '/ədˈvɑːns/', '进步;进展;前进', 'Which advance in technology would you most like to have in your future home?', '你最希望未来的家里拥有哪一项科技进步?', 'Future Living', 40, 0, 'senior', 'wordlist', 'elective1', 'U4', 'advances in technology', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'fancy', 'v.', '/ˈfænsi/', '想要;想做;喜欢', 'The future home will be any size you fancy at the moment.', '未来的家会随你心意变成任何你想要的大小。', 'Future Living', 41, 0, 'senior', 'wordlist', 'elective1', 'U4', 'fancy doing sth', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'reality', 'n.', '/riˈæləti/', '现实;事实', 'The smart home is no longer science fiction; it is becoming a reality.', '智能家居不再是科幻小说,它正在变成现实。', 'Future Living', 42, 0, 'senior', 'wordlist', 'elective1', 'U4', 'become a reality', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'device', 'n.', '/dɪˈvaɪs/', '设备;装置', 'You can connect all the smart devices in your home so they talk to each other.', '你可以连接家里所有的智能设备,让它们彼此通信。', 'Future Living', 43, 0, 'senior', 'wordlist', 'elective1', 'U4', 'smart devices', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'network', 'n.', '/ˈnetwɜːk/', '网络;网状系统', 'Any device that uses electricity can be added to your home network.', '任何用电的设备都可以加入你的家庭网络。', 'Future Living', 44, 0, 'senior', 'wordlist', 'elective1', 'U4', 'a home network', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'leisure', 'n.', '/ˈleʒə(r)/', '空闲;闲暇', 'Living in a smart home, you will enjoy much more leisure time.', '住在智能家居里,你会享有多得多的闲暇时间。', 'Future Living', 45, 0, 'senior', 'wordlist', 'elective1', 'U4', 'leisure time', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'independently', 'adv.', '/ˌɪndɪˈpendəntli/', '独立地;自立地', 'Smart homes are especially useful for elderly people who wish to live independently.', '智能家居对希望独立生活的老年人尤其有用。', 'Future Living', 46, 0, 'senior', 'wordlist', 'elective1', 'U4', 'live independently', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'perform', 'v.', '/pəˈfɔːm/', '执行;做;表演', 'Robots now work in labs and even perform surgery in hospitals.', '如今机器人在实验室工作,甚至在医院做手术。', 'Future Living', 47, 0, 'senior', 'wordlist', 'elective1', 'U4', 'perform surgery', NULL, 'sufe');
INSERT INTO public.junior_vocab (grade, word, pos, phonetic, meaning_cn, example_en, example_cn, theme, freq_rank, star_level, stage, source_type, volume, unit, phrase_en, tip, publisher) VALUES (11, 'landscape', 'n.', '/ˈlændskeɪp/', '风景;景色;地貌', 'I walk to the window and look out over the grey landscape of the city.', '我走到窗前,望着城市灰蒙蒙的景色。', 'Future Living', 48, 0, 'senior', 'wordlist', 'elective1', 'U4', 'look out over the landscape', NULL, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se1u4.01', '①which 引导非限制性(指物或整个主句)', 'A2', 11, '上外版选择性必修第一册 U4 — 逗号后用 which 补充说明前面的某个事物,或用 which 指代整个主句的内容(The dome house, which is energy-saving, …;Tom passed, which pleased us)。非限制性不可用 that。', 1, 'elective1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se1u4.02', '②who / whom 引导非限制性(指人)', 'A2', 11, '上外版选择性必修第一册 U4 — 逗号后用 who(从句缺主语)或 whom(从句缺宾语/介词后)补充说明前面的人(My uncle, who lives in Shanghai, …;Lina, whom we trust, …)。非限制性不可用 that。', 2, 'elective1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_points (code, title, cefr, grade, summary, sort_order, volume, unit, category_id, examples, content_depth, publisher) VALUES ('se1u4.03', '③whose / where / when 引导非限制性 + 与限制性辨析', 'A2', 11, '上外版选择性必修第一册 U4 — 逗号后用 whose(所属)、where(地点)、when(时间)补充说明;并辨析:有逗号→非限制性(禁 that、关系词不可省);无逗号且从句缺主宾→限制性(可用 that)。', 3, 'elective1', 'U4', (SELECT id FROM public.junior_grammar_categories WHERE code='senior' LIMIT 1), '[]'::jsonb, 0, 'sufe');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.01'), 'The dome house, ____ is energy-saving, needs very little power to heat.', 'which', 'who', 'where', 'that', 'A', '逗号后补充说明 house(指物)→ which;非限制性禁用 that。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.01'), 'My new smartphone, ____ I bought last year, controls every device at home.', 'who', 'which', 'when', 'that', 'B', '逗号后补充说明 smartphone(指物、从句缺宾语)→ which。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.01'), 'The walls can move backwards, ____ makes the living room any size you fancy.', 'who', 'where', 'which', 'that', 'C', 'which 指代整个主句的内容(墙能移动这件事)→ which;非限制性禁 that。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.01'), 'The smart system filters the air, ____ then carries your favourite perfume.', 'who', 'where', 'when', 'which', 'D', '逗号后补充说明 air(指物)→ which。', 2, 4, 'mcq');
