INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.02'), 'The housekeeper, ____ has been with the family for years, knows every routine.', 'which', 'where', 'who', 'that', 'C', '逗号后补充说明 housekeeper(指人、缺主语)→ who。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.02'), 'Our neighbour, ____ a robot company recently hired, tests new home gadgets.', 'which', 'where', 'when', 'whom', 'D', '逗号后补充说明 neighbour(指人、hired 缺宾语)→ whom。', 2, 20, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'The boy, ____ mother had passed away, lived alone with a robot servant.', 'whose', 'which', 'where', 'that', 'A', '逗号后表所属(boy 的 mother)→ whose;非限制性禁 that。', 2, 1, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'Margie went up to the attic, ____ Tommy had found the very old book.', 'which', 'where', 'who', 'that', 'B', '逗号后补充说明地点 attic、从句完整 → where。', 2, 2, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'It was the year 2157, ____ children learned everything from a mechanical teacher.', 'which', 'where', 'when', 'that', 'C', '逗号后补充说明时间 2157、从句完整 → when。', 2, 3, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'This is the smart home ____ controls the lights, heating and security for you.', 'where', 'when', 'whose', 'that', 'D', '无逗号、限制性、从句缺主语、先行词指物 → that(限制性可用 that)。', 2, 4, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'The dome house, ____ roof is covered with solar panels, needs almost no power.', 'whose', 'which', 'where', 'that', 'A', '逗号后表所属(house 的 roof)→ whose。', 2, 5, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'We walked into a huge hall, ____ the simulator could create any adventure we liked.', 'which', 'where', 'who', 'that', 'B', '逗号后补充说明地点 hall、从句完整 → where。', 2, 6, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'I still remember the morning, ____ my lights first turned on all by themselves.', 'which', 'where', 'when', 'that', 'C', '逗号后补充说明时间 morning、从句完整 → when。', 2, 7, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'The appliance ____ I attached to the power wall started working at once.', 'where', 'when', 'whose', 'that', 'D', '无逗号、限制性、从句缺宾语、先行词指物 → that。', 2, 8, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'Lina, ____ metallic voice echoed around the room, told me not to be late.', 'whose', 'which', 'where', 'that', 'A', '逗号后表所属(Lina 的 voice)→ whose。', 2, 9, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'He took me to the laboratory, ____ all the food for the city is now grown.', 'which', 'where', 'who', 'that', 'B', '逗号后补充说明地点 laboratory、从句完整 → where。', 2, 10, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'Mum often talks about the old days, ____ people could buy food at the market.', 'which', 'where', 'when', 'that', 'C', '逗号后补充说明时间 the old days、从句完整 → when。', 2, 11, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'The reason ____ they bought the robot was that they had no time for children.', 'where', 'when', 'whose', 'that', 'D', '无逗号、限制性、the reason 后从句缺原因状语,口语中常用 that 替代 why → that。', 2, 12, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'Tommy, ____ house had an old attic, kept finding strange things up there.', 'whose', 'which', 'where', 'that', 'A', '逗号后表所属(Tommy 的 house)→ whose。', 2, 13, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'I rushed down to the lobby, ____ the other children in my building gathered.', 'which', 'where', 'who', 'that', 'B', '逗号后补充说明地点 lobby、从句完整 → where。', 2, 14, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'Things went wrong on the day, ____ the Earth was passing close to Jupiter.', 'which', 'where', 'when', 'that', 'C', '逗号后补充说明时间 the day、从句完整 → when。', 2, 15, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'The smart device ____ connects all the others is the home computer itself.', 'where', 'when', 'whose', 'that', 'D', '无逗号、限制性、从句缺主语、先行词指物 → that。', 2, 16, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'The surgeon, ____ skill once amazed everyone, was replaced by a clever zoid.', 'whose', 'which', 'where', 'that', 'A', '逗号后表所属(surgeon 的 skill)→ whose。', 2, 17, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'We moved to a new flat, ____ every wall could slide to change the room size.', 'which', 'where', 'who', 'that', 'B', '逗号后补充说明地点 flat、从句完整 → where。', 2, 18, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'I look forward to the time, ____ a home robot will do all the boring chores.', 'which', 'where', 'when', 'that', 'C', '逗号后补充说明时间 the time、从句完整 → when。', 2, 19, 'mcq');
INSERT INTO public.junior_grammar_questions (point_id, stem, option_a, option_b, option_c, option_d, correct_answer, explanation, difficulty, sort_order, question_type) VALUES ((SELECT id FROM public.junior_grammar_points WHERE publisher='sufe' AND volume='elective1' AND unit='U4' AND code='se1u4.03'), 'The robot ____ the company advertised as reliable soon became very popular.', 'where', 'when', 'whose', 'that', 'D', '无逗号、限制性、从句缺宾语、先行词指物 → that。', 2, 20, 'mcq');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Welcome to the Smart Home', 'When you are out, small doubts can crowd your mind. Did I turn the lights off? Is the room too cold for my pet? In a smart home, you can quiet all these worries with a quick look at your phone. Every device that uses electricity can be added to one home network and placed under your control. Most of these devices deal with lighting, temperature, home security and cleaning chores. As an electronic servant takes over almost all the housework, you will enjoy far more leisure time, and old-fashioned tools such as the duster will slowly disappear. Much of this is thanks to the huge success of smartphones and tablets. These tiny computers are everywhere, and their always-on connections mean they can manage many online gadgets at once. The idea may sound like science fiction, but the technology is real and growing smarter every year. It is especially useful for elderly people and people with disabilities who wish to live independently.', '说明·智能家居如何运作', 162, '[{"q":"How can a smart home quiet your worries when you are out?","answer":"A","options":["By letting you check and control things from your phone.","By sending a servant to your office.","By switching off all power at night.","By calling your neighbours for help."],"explanation":"原文 ''quiet all these worries with a quick look at your phone'' 的转述。"},{"q":"What happens to old-fashioned tools like the duster?","answer":"B","options":["They become more expensive.","They will slowly disappear.","They are sold to museums.","They control the lighting."],"explanation":"原文 ''old-fashioned tools such as the duster will slowly disappear'' 的转述。"},{"q":"Who does the writer say smart homes are especially useful for?","answer":"A","options":["Elderly people and those with disabilities.","Only rich families.","Children who hate school.","People who never use phones."],"explanation":"末句 ''especially useful for elderly people and people with disabilities'' 的转述。"}]'::jsonb, '[{"word":"device","cn":"设备"},{"word":"network","cn":"网络"},{"word":"security","cn":"安全"},{"word":"leisure","cn":"闲暇"}]'::jsonb, 2, 'elective1', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A House Under a Glass Dome', 'Imagine a home built under a huge glass dome. Because you are always indoors, it needs only a tiny amount of energy to stay warm, and most of that power comes from solar panels in the round roof above you. At the heart of the house sits a home computer that acts as a quiet electronic servant. It controls the temperature, the humidity and the lighting, and it even pays your bills and orders your food. Having friends over? Push a button and the walls move backwards to make the living room larger; push it again and the room shrinks once your guests have gone. There are no electric sockets here. Instead, each room has a power wall, and you simply attach any appliance you like to its surface. The good old duster is gone, too, for the air is filtered and then scented with your favourite perfume. Such a home brings nature close while keeping you safe and comfortable inside.', '说明·玻璃穹顶之家', 161, '[{"q":"Why does the dome house need very little energy to heat?","answer":"B","options":["Because nobody lives in it.","Because you stay indoors and solar panels supply the power.","Because the windows are always open.","Because it is never used in winter."],"explanation":"原文 ''always indoors… most of that power comes from solar panels'' 的转述。"},{"q":"How do you change the size of the living room?","answer":"C","options":["You wait for the dome to grow.","You ask a servant to rebuild it.","You push a button to move the walls.","You turn off the lights."],"explanation":"原文 ''Push a button and the walls move backwards… push it again and the room shrinks'' 的转述。"},{"q":"What replaces the electric sockets in this house?","answer":"D","options":["A large battery box.","Long cables on the floor.","Nothing at all.","A power wall you attach appliances to."],"explanation":"原文 ''each room has a power wall… attach any appliance'' 的转述。"}]'::jsonb, '[{"word":"dome","cn":"穹顶"},{"word":"humidity","cn":"湿度"},{"word":"socket","cn":"插座"},{"word":"scent","cn":"使具香味"}]'::jsonb, 2, 'elective1', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'When Robots Take Over the Jobs', 'In the world of 2050, robots are everywhere, and people simply call them zoids. When they first appeared on the market around 2030, everyone wanted one, and twenty years later they have taken over almost every kind of work. Zoids labour in factories and laboratories, fix teeth and even perform surgery in hospitals. One boy''s father used to be a surgeon, but he changed his job once people found that zoids could operate with less room for error than any human hand. Food, too, is now grown in laboratories rather than in fields, and every home receives just enough of it, no more and no less, because the planet can no longer deal with overpopulation. Some people welcome this change, saying that machines free us from boring and dangerous tasks. Others worry that humans may slowly forget how to do things for themselves. Whether we like it or not, such a future seems to be on its way, and we will have to decide what kind of work we still want to keep.', '议论·机器人取代工作', 173, '[{"q":"Why did the boy''s father stop working as a surgeon?","answer":"A","options":["Zoids could operate more accurately than people.","He grew too old for the job.","Hospitals closed in 2050.","He decided to grow food instead."],"explanation":"原文 ''zoids could operate with less room for error than any human hand'' 的转述。"},{"q":"Why does each home receive only a limited amount of food?","answer":"B","options":["Because too many people now share too little space.","Because Earth now holds far too many people for its space.","Because robots eat most of it.","Because people prefer to stay hungry."],"explanation":"原文 ''just enough… because the planet can no longer deal with overpopulation'' 的转述。"},{"q":"What worries some people about a world full of zoids?","answer":"C","options":["That robots will run out of power.","That food will taste strange.","That people might lose the skill of looking after themselves.","That factories will be too quiet."],"explanation":"原文 ''humans may slowly forget how to do things for themselves'' 的转述。"}]'::jsonb, '[{"word":"perform","cn":"执行;做"},{"word":"error","cn":"差错"},{"word":"overpopulation","cn":"人口过剩"}]'::jsonb, 2, 'elective1', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'Lina, My Family''s Housekeeper', 'My lights turn on by themselves each morning, and at ten to seven the house gently wakes me up. Still sleepy, I find my school uniform in the wardrobe, already washed, ironed and hung up the night before by Lina X15, my family''s housekeeper. When I was little, she was my nanny, and she has been by my side for my whole life. My parents had no time for children back then, so they bought Lina, who had been advertised as a reliable helper, to look after me. Almost every family has an X15 today. My breakfast is always waiting for me in the kitchen, planned and served in a carefully controlled quantity. As I leave my room, I feel a light tap on my shoulder and turn around. It is Lina, her metallic voice echoing softly through the room, reminding me not to be late for school. ''On my way,'' I answer, and I promise to be home again by six. Sometimes I wonder what life would be like without her.', '记叙·家用机器人 X15', 172, '[{"q":"Why did the writer''s parents buy Lina?","answer":"D","options":["They wanted a robot to drive their car.","They were told every house must own one.","They hoped to sell her later.","They were too busy to raise him and wanted a helper."],"explanation":"原文 ''My parents had no time for children… bought Lina… to look after me'' 的转述。"},{"q":"What had Lina done with the uniform before the boy woke up?","answer":"A","options":["She had washed, ironed and hung it up.","She had hidden it in the attic.","She had thrown it away.","She had sold it at the market."],"explanation":"原文 ''already washed, ironed and hung up the night before'' 的转述。"},{"q":"How does the writer seem to feel about Lina by the end?","answer":"B","options":["Angry and afraid of her.","Thoughtful, even a little attached to her.","Bored and uninterested.","Sure that he no longer needs her."],"explanation":"末句 ''I wonder what life would be like without her'' 暗示依赖与思考的转述。"}]'::jsonb, '[{"word":"wardrobe","cn":"衣柜"},{"word":"nanny","cn":"保姆"},{"word":"quantity","cn":"数量"}]'::jsonb, 2, 'elective1', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'A City of Grey Towers', 'I walk to the window and look out over the landscape of my city. All I can see are buildings and the tunnels that interconnect them. Grey skyscrapers rise everywhere, and they are all identical, like boxes stacked toward the sky. I try to spot my school, which is just over to the right, but it looks the same as every other tower around it. Today a lecturer is coming to speak to us about the extinction of animals such as the polar bear and the elephant. I find it strange that, even with all our clever technology, we still could not save them. To reach school, we go down sixty floors and walk through the tunnels with the other children in our building. We have always breathed recycled air, and none of us has ever been outside. I often wonder what the open sky feels like, and whether the wind is warm or cold. Perhaps one day Lina can explain it to me, or perhaps I will simply have to imagine it.', '记叙·未来城市景观', 173, '[{"q":"What does the writer see when looking out of the window?","answer":"C","options":["Green fields and rivers.","A busy market by the sea.","Grey towers and connecting tunnels that all look alike.","Animals running in the wild."],"explanation":"原文 ''Grey skyscrapers… all identical… tunnels that interconnect them'' 的转述。"},{"q":"What does the writer find strange about their technology?","answer":"D","options":["That it makes the city too colourful.","That it cannot build tall towers.","That it works only at night.","That it could not save animals from dying out."],"explanation":"原文 ''even with all our clever technology, we still could not save them'' 的转述。"},{"q":"Why has the writer never felt the open sky?","answer":"A","options":["Because the children live indoors and breathe recycled air.","Because the school has no windows.","Because the city is always dark.","Because the wind is forbidden."],"explanation":"原文 ''always breathed recycled air, and none of us has ever been outside'' 的转述。"}]'::jsonb, '[{"word":"landscape","cn":"景色"},{"word":"skyscraper","cn":"摩天大楼"},{"word":"identical","cn":"完全相同的"},{"word":"recycle","cn":"回收利用"}]'::jsonb, 2, 'elective1', 'U4', 'sufe');
INSERT INTO public.junior_reading (grade, title, body, topic, word_count, questions, vocab_notes, difficulty, volume, unit, publisher) VALUES (11, 'What Will Future Humans Be Like', 'Scientists enjoy guessing how human beings might change over the next thousands of years. Some believe we will keep growing taller, since better food and care help each new generation reach a greater height. Because we will use our brains more and more, the forehead may grow larger to make room inside the head. Our eyes, which we rely on so heavily to read screens, are likely to become stronger over a very long period of time. Arms and legs, on the other hand, may grow weaker, for machines now do much of the heavy work that muscles once handled. Fingers, however, could become more skilful, as we use them all day long to tap and type. Even hair might one day disappear from the body, simply because it no longer serves any clear purpose. Of course, no one can be certain that these predictions will come true. They are only educated guesses, yet they remind us that, just like our homes and cities, human beings themselves never stop changing.', '说明·未来人类的样子', 170, '[{"q":"Why might the human forehead grow larger in the future?","answer":"B","options":["Because people will wear bigger hats.","Because greater use of the brain may need more space.","Because the air will be cleaner.","Because hair will cover it."],"explanation":"原文 ''use our brains more… the forehead may grow larger to make room'' 的转述。"},{"q":"Why might arms and legs become weaker?","answer":"C","options":["Because people will stop eating well.","Because the weather will get colder.","Because machines do most of the heavy work for us.","Because we will grow much taller."],"explanation":"原文 ''machines now do much of the heavy work that muscles once handled'' 的转述。"},{"q":"How does the writer describe these ideas about the future?","answer":"D","options":["As proven scientific facts.","As silly stories with no value.","As warnings of certain danger.","As educated guesses that may or may not come true."],"explanation":"原文 ''only educated guesses… no one can be certain'' 的转述。"}]'::jsonb, '[{"word":"generation","cn":"一代人"},{"word":"forehead","cn":"前额"},{"word":"purpose","cn":"目的"}]'::jsonb, 2, 'elective1', 'U4', 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U4', 'My Home in My Pocket', 'I used to worry all day about whether I had turned off the lights or locked the (1)____. Now my whole home sits in my pocket. With one (2)____ on my phone, I can change the lighting, check the temperature and watch the front door. Every (3)____ that uses electricity is joined to a single home (4)____, so they can talk to one another and to me. If a window is left open, the system sends me a quiet (5)____ at once. The home computer even pays the (6)____ and orders food when the fridge is almost empty. Because it takes (7)____ most of the boring housework, I now enjoy much more (8)____ time after school. My grandmother thinks it all sounds like science (9)____, but the technology is completely (10)____. Little by little, our home has learned to look after us.', 142, 2, '[{"q":"1","answer":"A","options":["door","sky","river","tree"],"explanation":"locked the door 锁门。"},{"q":"2","answer":"B","options":["forest","tap","ocean","garden"],"explanation":"one tap on my phone 在手机上轻点一下。"},{"q":"3","answer":"C","options":["song","price","device","weather"],"explanation":"every device 每件设备。"},{"q":"4","answer":"D","options":["market","garden","machine","network"],"explanation":"home network 家庭网络。"},{"q":"5","answer":"A","options":["message","garden","price","stone"],"explanation":"a quiet message 一条提示信息。"},{"q":"6","answer":"B","options":["trees","bills","songs","stars"],"explanation":"pays the bills 付账单。"},{"q":"7","answer":"C","options":["off","up","over","in"],"explanation":"take over 接管。"},{"q":"8","answer":"D","options":["angry","empty","rainy","leisure"],"explanation":"leisure time 闲暇时间。"},{"q":"9","answer":"A","options":["fiction","market","garden","machine"],"explanation":"science fiction 科幻小说。"},{"q":"10","answer":"B","options":["wrong","real","empty","asleep"],"explanation":"completely real 完全真实。"}]'::jsonb, 1, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U4', 'The Power Wall', 'When we moved into our new flat, the first thing I noticed was that there were no electric (1)____ on the walls. At first I thought something was (2)____, but my father just smiled. Instead of old plugs, each room has a smart power (3)____. You simply (4)____ any appliance you like to its surface, and it begins to work straight (5)____. There are no cables to trip over and no plugs to (6)____. The wall can power a lamp, a fan or a small (7)____ at the same time. Even better, it knows how much (8)____ each device needs, so nothing is ever wasted. My little brother loves to (9)____ his toy car onto the wall and watch its lights come on. Such a simple idea has made our home far (10)____ and much tidier than before.', 138, 2, '[{"q":"1","answer":"C","options":["rivers","songs","sockets","clouds"],"explanation":"electric sockets 电源插座。"},{"q":"2","answer":"D","options":["sweet","loud","warm","wrong"],"explanation":"something was wrong 出了问题。"},{"q":"3","answer":"A","options":["wall","garden","market","song"],"explanation":"power wall 电力墙。"},{"q":"4","answer":"B","options":["throw","attach","sell","eat"],"explanation":"attach any appliance 把电器附上去。"},{"q":"5","answer":"C","options":["down","off","away","up"],"explanation":"straight away 立刻。"},{"q":"6","answer":"D","options":["sing","fly","swim","break"],"explanation":"plugs to break 会损坏的插头。"},{"q":"7","answer":"A","options":["appliance","river","cloud","garden"],"explanation":"a small appliance 一件小电器。"},{"q":"8","answer":"B","options":["water","power","snow","rain"],"explanation":"how much power 需要多少电。"},{"q":"9","answer":"C","options":["lose","sell","attach","hide"],"explanation":"attach his toy car 把玩具车贴上去。"},{"q":"10","answer":"D","options":["worse","darker","colder","safer"],"explanation":"far safer 安全得多。"}]'::jsonb, 2, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U4', 'Breakfast Made by a Robot', 'Every morning my breakfast is already (1)____ for me on the kitchen table. I never have to cook, because a robot (2)____ does it all. It plans each meal with a carefully controlled (3)____, so I am given just enough food, no more and no (4)____. The government says our planet can no longer deal with (5)____, and so every home receives the same fair share. My mother often talks about the old (6)____ when people grew vegetables in their own gardens. Back then, animals lived in the (7)____ and not in carefully managed zoos. To me, however, robot meals are simply all I have ever (8)____. The food is healthy and never (9)____, yet sometimes I dream of choosing my own dishes. I wonder whether future children will think a kitchen robot is (10)____ or strange.', 137, 2, '[{"q":"1","answer":"A","options":["waiting","crying","sleeping","flying"],"explanation":"breakfast is waiting 早餐已备好。"},{"q":"2","answer":"B","options":["river","housekeeper","garden","market"],"explanation":"a robot housekeeper 机器人管家。"},{"q":"3","answer":"C","options":["song","cloud","quantity","weather"],"explanation":"controlled quantity 受控的数量。"},{"q":"4","answer":"D","options":["more","rain","snow","less"],"explanation":"no more, no less 不多不少。"},{"q":"5","answer":"A","options":["overpopulation","music","sunshine","holidays"],"explanation":"deal with overpopulation 应对人口过剩。"},{"q":"6","answer":"B","options":["prices","days","songs","clouds"],"explanation":"the old days 过去的日子。"},{"q":"7","answer":"C","options":["market","office","wild","garden"],"explanation":"lived in the wild 生活在野外。"},{"q":"8","answer":"D","options":["sold","lost","broken","known"],"explanation":"all I have ever known 我所知道的一切。"},{"q":"9","answer":"A","options":["wasted","happy","afraid","quiet"],"explanation":"never wasted 从不被浪费。"},{"q":"10","answer":"B","options":["loud","normal","wet","asleep"],"explanation":"think it normal 觉得正常。"}]'::jsonb, 3, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U4', 'Air Under the Dome', 'In our dome house, the old dusty days are completely (1)____. There is no need for the good old (2)____ any more, because the home looks after the air by itself. First, the system (3)____ the air to remove every bit of dust. Then it adds your favourite (4)____, so each room smells fresh and clean. Because we live under a clear glass (5)____, sunlight pours in all day, and most of our power comes from solar (6)____ above us. The temperature and the (7)____ are kept just right, so the rooms never feel too dry or too damp. When friends come over, we push a (8)____ and the walls move to make the living room (9)____. Living here feels healthy and calm, and I can hardly imagine going back to an (10)____ house with open windows and dusty corners.', 140, 2, '[{"q":"1","answer":"C","options":["wet","loud","gone","rich"],"explanation":"are gone 消失了。"},{"q":"2","answer":"D","options":["river","garden","market","duster"],"explanation":"the good old duster 那把老抹布。"},{"q":"3","answer":"A","options":["filters","sells","eats","throws"],"explanation":"filters the air 过滤空气。"},{"q":"4","answer":"B","options":["price","perfume","noise","stone"],"explanation":"your favourite perfume 你最爱的香味。"},{"q":"5","answer":"C","options":["market","river","dome","song"],"explanation":"glass dome 玻璃穹顶。"},{"q":"6","answer":"D","options":["songs","clouds","prices","panels"],"explanation":"solar panels 太阳能电池板。"},{"q":"7","answer":"A","options":["humidity","river","garden","market"],"explanation":"the humidity 湿度。"},{"q":"8","answer":"B","options":["cloud","button","song","river"],"explanation":"push a button 按按钮。"},{"q":"9","answer":"C","options":["colder","darker","larger","wetter"],"explanation":"make the room larger 把房间变大。"},{"q":"10","answer":"D","options":["happy","quiet","clever","old-fashioned"],"explanation":"an old-fashioned house 一座旧式房子。"}]'::jsonb, 4, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U4', 'Cars That Drive Themselves', 'On my way to school each morning, I climb into a car that has no (1)____ wheel at all. The car drives itself, and I just sit back and (2)____. Experts say that within a few years, millions of self-driving cars will be on the (3)____. These clever machines can (4)____ other cars, people and traffic lights, so they hardly ever make an (5)____. While the car carries me to school, I can read a book or finish my (6)____. The streets feel much (7)____ now, because the cars never grow tired or angry. Of course, some older people still do not (8)____ the new cars, and they miss driving with their own (9)____. For me, however, a car that drives itself is simply part of everyday (10)____, and I cannot imagine travelling any other way.', 136, 2, '[{"q":"1","answer":"A","options":["steering","happy","rainy","loud"],"explanation":"no steering wheel 没有方向盘。"},{"q":"2","answer":"B","options":["cry","relax","shout","fall"],"explanation":"sit back and relax 放松。"},{"q":"3","answer":"C","options":["sky","sea","road","cloud"],"explanation":"on the road 在路上。"},{"q":"4","answer":"D","options":["eat","sell","throw","spot"],"explanation":"spot other cars 注意到其他车辆。"},{"q":"5","answer":"A","options":["error","garden","song","river"],"explanation":"make an error 出错。"},{"q":"6","answer":"B","options":["garden","homework","market","weather"],"explanation":"finish my homework 完成作业。"},{"q":"7","answer":"C","options":["worse","darker","safer","colder"],"explanation":"much safer 安全得多。"},{"q":"8","answer":"D","options":["lose","sell","drop","trust"],"explanation":"do not trust 不信任。"},{"q":"9","answer":"A","options":["hands","songs","clouds","prices"],"explanation":"with their own hands 用自己的双手。"},{"q":"10","answer":"B","options":["song","life","price","cloud"],"explanation":"everyday life 日常生活。"}]'::jsonb, 5, 'sufe');
INSERT INTO public.junior_cloze (grade, volume, unit, title, body, word_count, difficulty, questions, sort_order, publisher) VALUES (11, 'elective1', 'U4', 'A Class Debate about AI', 'Today our class held a (1)____ about whether robots make people more or less clever. Anna spoke first and (2)____ that machines free us from boring tasks, so we have more time to think. She gave a clear (3)____: a kitchen robot cooks dinner while she reads a good book. Ben did not fully (4)____. He said that if robots do everything, people may slowly (5)____ how to do simple things by themselves. Our teacher reminded us that it is not (6)____ to say only ''I agree'' or ''I disagree''; we must give good (7)____ to support our views. In the end, most of us felt that robots can be helpful, but only if we stay in (8)____ of them. Technology is (9)____ our world very quickly, yet the most important choices are still (10)____ by humans, not by machines.', 140, 2, '[{"q":"1","answer":"C","options":["garden","river","debate","market"],"explanation":"held a debate 举行辩论。"},{"q":"2","answer":"D","options":["cried","slept","flew","argued"],"explanation":"argued that 主张。"},{"q":"3","answer":"A","options":["example","price","noise","stone"],"explanation":"a clear example 一个清楚的例子。"},{"q":"4","answer":"B","options":["sell","agree","lose","throw"],"explanation":"did not fully agree 没有完全同意。"},{"q":"5","answer":"C","options":["buy","sell","forget","open"],"explanation":"forget how to 忘记如何。"},{"q":"6","answer":"D","options":["rainy","happy","loud","enough"],"explanation":"not enough 不够。"},{"q":"7","answer":"A","options":["reasons","clouds","songs","prices"],"explanation":"give good reasons 给出充分理由。"},{"q":"8","answer":"B","options":["song","control","river","garden"],"explanation":"stay in control 保持掌控。"},{"q":"9","answer":"C","options":["losing","selling","changing","eating"],"explanation":"changing our world 改变世界。"},{"q":"10","answer":"D","options":["sold","lost","eaten","made"],"explanation":"made by humans 由人类做出。"}]'::jsonb, 6, 'sufe');
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·对话 Which Technology Would You Choose', '上外版选择性必修第一册 U4 · dialogue', 3, 'Mia: If you could have one piece of future technology at home, what would you choose?
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·短文 What a Smart Home Can Do', '上外版选择性必修第一册 U4 · passage', 2, 'A smart home connects every device into one network.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·对话 A Visit to the Dome House', '上外版选择性必修第一册 U4 · dialogue', 3, 'Guide: Welcome to the dome house. Notice the clear glass roof above us.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·短文 How Humans May Change', '上外版选择性必修第一册 U4 · passage', 2, 'Scientists make some interesting predictions about future humans.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·对话 Asking the Home Robot for Help', '上外版选择性必修第一册 U4 · dialogue', 3, 'Sam: Lina, I can''t find my school uniform anywhere.
INSERT INTO public.junior_listening_exercises (grade, title, topic, difficulty, transcript, translation_cn, speaker, questions, key_vocab, kind, volume, unit, publisher) VALUES (11, 'U4 听力·短文 Living Well in the Future', '上外版选择性必修第一册 U4 · passage', 2, 'Technology can make our future homes very comfortable.
INSERT INTO public.junior_writing_prompts (grade, topic, title_en, prompt_cn, prompt_en, requirements, min_words, max_words, sample_answer, scoring_rubric, high_sentences, error_pairs, paragraph_template, difficulty, volume, unit, publisher) VALUES (11, 'Describe Your Future Home(描写你未来的家)', 'My Future Home', '假设你叫李华,学校英语角以"未来生活"为主题征文。请用英语写一篇约100词的短文,描写你想象中的未来之家,内容包括:① 这个家是什么样子(智能家居/穹顶/电力墙等);② 它有哪些功能让生活更方便(家务/温度/空气等);③ 你对住在那里的感受。注意:适当使用非限制性定语从句(…, which … / …, who …),句句围绕中心。', 'Suppose you are Li Hua. Your school''s English Corner is collecting short pieces on the theme ''Future Living''. Write about 100 words describing your imagined future home, including: 1) what the home looks like (e.g. a smart home, a glass dome, a power wall); 2) the functions that make life easier (housework, temperature, air, etc.); 3) how you would feel living there. Try to use non-defining relative clauses (…, which … / …, who …).', '["描写外观(My future home is a smart house under a glass dome, which …)","列举便利功能(An electronic servant, who never gets tired, does all the housework.)","表达感受(Living there would feel comfortable and free.)","适当使用非限制性定语从句、句句围绕中心"]'::jsonb, 70, 100, 'My future home is a smart house built under a clear glass dome, which lets in plenty of sunlight. Most of its power comes from solar panels, so it needs very little energy to run. At its heart is a home computer, which controls the lighting, the temperature and the air. There is also a friendly robot servant, who does all the boring housework and never gets tired. When friends come over, I push a button and the walls move to make the living room larger. Living in such a home, where everything is clean and quiet, would feel both comfortable and free.', '【15 分制】A 档(13-15):五要素齐全、组织有条理、语言准确多样;B 档(10-12):要点较全、少量错误;C 档(7-9):要点偏少、句型简单;D 档(0-6):内容不完整、错误多。', '["My future home is a smart house built under a clear glass dome, which lets in plenty of sunlight.","At its heart is a home computer, which controls the lighting, the temperature and the air.","There is a friendly robot servant, who does all the boring housework and never gets tired.","Living in such a home, where everything is clean and quiet, would feel both comfortable and free."]'::jsonb, '[{"wrong":"My home, that has a glass dome, is very bright.","correct":"My home, which has a glass dome, is very bright.","note":"非限制性定语从句(有逗号)不能用 that,指物用 which。"},{"wrong":"The robot servant which does the housework never gets tired.","correct":"The robot servant, who does the housework, never gets tired.","note":"补充说明的人用 who,且非限制性需加逗号。"},{"wrong":"Solar panels gives the home most of its power.","correct":"Solar panels give the home most of its power.","note":"主语为复数,动词用原形 give。"}]'::jsonb, '【未来之家结构】
INSERT INTO public.junior_grammar_tips (grade, volume, unit, content, publisher) VALUES (11, 'elective1', 'U4', '{"title":"非限制性定语从句 速查","intro":"非限制性定语从句用逗号和主句隔开,只是对先行词作补充说明(去掉它句子意思仍完整)。核心三铁律:① 必须有逗号;② 禁用 that;③ 关系词不可省。指人用 who/whom,指物用 which,还可用 which 指代整个主句;另有 whose(所属)、where(地点)、when(时间)。","table":{"headers":["关系词","用法 / 例句"],"rows":[["which","指物 / 指整个主句:The dome, which is energy-saving, …;He passed, which pleased us."],["who / whom","指人(who 作主语 / whom 作宾语):My uncle, who lives here, …;Lina, whom we trust, …"],["whose","表所属:The boy, whose mother had died, …"],["where / when","地点 / 时间:the attic, where Tommy found it …;2157, when children …"]]},"specialRules":[{"rule":"非限制性必须有逗号,且禁用 that","mark":"…, which … √ / …, that … ×"},{"rule":"关系词在非限制性从句中不可省略","mark":"My phone, which I bought last year, …(which 不能省)"},{"rule":"which 可指代前面整个主句(逗号 + which)","mark":"Robots took over, which gave us more time."},{"rule":"限制性(无逗号、缺主宾)指物可用 that;非限制性不可","mark":"the device that connects all(限制性)√"}],"why":["限制性从句帮你''锁定''是哪一个(去掉句意残缺);非限制性只是''顺带多说一句''(去掉句意仍完整)。正因为它只是补充,所以用逗号隔开、不能用 that、关系词也不能省。"],"gaokaoPoints":["逗号判定:有逗号→非限制性(禁 that、禁省略);看从句缺什么成分定 who/which(缺主宾)还是 where/when(缺状语)。","which 指代整个主句(语法填空与改错高频);whose 表所属;非限制性禁 that 是常见陷阱。"],"examVsReal":[{"exam":"Lina, who looks after me, never gets tired.（考试 / 书面）","real":"Lina looks after me — she never gets tired.","note":"考试爱考非限制性从句;口语常拆成两个短句或破折号。"},{"exam":"He passed the test, which pleased his parents.（考试)","real":"He passed the test, and that pleased his parents.","note":"which 指代整句;口语里也常用 and that 表达。"}]}'::jsonb, 'sufe');
